#ifndef LRUCache.hpp
#define LRUCache.hpp

#include <cstddef>
#include <optional>
#include <stdexcept>
#include <unordered_map>
#include <list>
#include <mutex>

template <typename K, typename V>
class LRUCache {
private:
    std::mutex mutex;
    std::size_t capacity;
    std::list<std::pair<K, V>> order;
    std::unordered_map<K, std::list<std::pair<K, V>>::iterator> cache;

public:
    explicit LRUCache(std::size_t capacity) : capacity(capacity) {
        if (capacity == 0) {
            throw std::invalid_argument("LRUCache capacity cannot be zero");
        }
    }

    std::optional<V> get(const K& key) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = cache.find(key);
        if (it == cache.end()) {
            return std::nullopt;
        }
        // Move accessed item to the front (most recently used).
        order.splice(order.begin(), order, it->second);
        return it->second->second;
    }

    void put(const K& key, const V& value) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = cache.find(key);
        if (it != cache.end()) {
            // Update existing key and move to front.
            order.splice(order.begin(), order, it->second);
            it->second->second = value;
        } else {
            // Evict least recently used if capacity reached.
            while (order.size() >= capacity) {
                const auto& evicting = order.back();
                order.pop_back();
                cache.erase(evicting.first);
            }
            // Insert new entry at the front.
            order.emplace_front(key, value);
            cache.emplace(key, order.begin());
        }
    }

    std::size_t size() const {
        std::lock_guard<std::mutex> lock(mutex);
        return order.size();
    }

    std::size_t getCapacity() const {
        std::lock_guard<std::mutex> lock(mutex);
        return capacity;
    }

    std::size_t sizeOfData() const {
        std::lock_guard<std::mutex> lock(mutex);
        std::size_t bytes = 0;
        for (const auto& item : order) {
            bytes += sizeof(item.first) + sizeof(item.second);
        }
        return bytes;
    }

    void setCapacity(std::size_t new_capacity) {
        std::lock_guard<std::mutex> lock(mutex);
        capacity = new_capacity;
        while (order.size() > capacity) {
            const auto& evicting = order.back();
            order.pop_back();
            cache.erase(evicting.first);
        }
    }

    bool erase(const K& key) {
        std::lock_guard<std::mutex> lock(mutex);
        if (cache.erase(key) == 0) {
            return false;
        }
        order.erase(order.begin() + std::distance(order.begin(), cache[key]));
        return true;
    }
};

#endif // LRUCache.hpp
