#include <stdexcept>
#include <utility>

class Matrix {
private:
    double* data_;
    int rows_;
    int cols_;

public:
    Matrix(int rows, int cols) : rows_(rows), cols_(cols), data_(new double[static_cast<size_t>(rows) * static_cast<size_t>(cols)]) {
        for (int i = 0; i < rows_; ++i) {
            for (int j = 0; j < cols_; ++j) {
                data_[static_cast<size_t>(i) * static_cast<size_t>(cols_) + j] = 0.0;
            }
        }
    }

    ~Matrix() {
        delete[] data_;
    }

    Matrix(const Matrix& other) : rows_(other.rows_), cols_(other.cols_), data_(new double[static_cast<size_t>(rows_) * static_cast<size_t>(cols_)]) {
        for (int i = 0; i < rows_; ++i) {
            for (int j = 0; j < cols_; ++j) {
                data_[static_cast<size_t>(i) * static_cast<size_t>(cols_) + j] = other.data_[static_cast<size_t>(i) * static_cast<size_t>(other.cols_) + j];
            }
        }
    }

    Matrix(Matrix&& other) noexcept : rows_(other.rows_), cols_(other.cols_), data_(other.data_) {
        other.data_ = nullptr;
        other.rows_ = 0;
        other.cols_ = 0;
    }

    Matrix& operator=(const Matrix& other) {
        if (this != &other) {
            delete[] data_;
            rows_ = other.rows_;
            cols_ = other.cols_;
            data_ = new double[static_cast<size_t>(rows_) * static_cast<size_t>(cols_)];

            for (int i = 0; i < rows_; ++i) {
                for (int j = 0; j < cols_; ++j) {
                    data_[static_cast<size_t>(i) * static_cast<size_t>(cols_) + j] = other.data_[static_cast<size_t>(i) * static_cast<size_t>(other.cols_) + j];
                }
            }
        }
        return *this;
    }

    Matrix& operator=(Matrix&& other) noexcept {
        if (this != &other) {
            delete[] data_;
            rows_ = other.rows_;
            cols_ = other.cols_;
            data_ = other.data_;
            other.data_ = nullptr;
            other.rows_ = 0;
            other.cols_ = 0;
        }
        return *this;
    }

    double& at(int r, int c) {
        if (r < 0 || r >= rows_ || c < 0 || c >= cols_) {
            throw std::out_of_range("Matrix::at: row out of range");
        }
        return data_[static_cast<size_t>(r) * static_cast<size_t>(cols_) + static_cast<size_t>(c)];
    }

    double at(int r, int c) const {
        if (r < 0 || r >= rows_ || c < 0 || c >= cols_) {
            throw std::out_of_range("Matrix::at: column out of range");
        }
        return data_[static_cast<size_t>(r) * static_cast<size_t>(cols_) + static_cast<size_t>(c)];
    }

    int rows() const {
        return rows_;
    }

    int cols() const {
        return cols_;
    }

    Matrix operator+(const Matrix& o) const {
        if (rows_ != o.rows_ || cols_ != o.cols_) {
            throw std::invalid_argument("Matrix addition: size mismatch");
        }
        Matrix result(rows_, cols_);
        for (int i = 0; i < rows_; ++i) {
            for (int j = 0; j < cols_; ++j) {
                result.at(i, j) = data_[static_cast<size_t>(i) * static_cast<size_t>(cols_) + j] + o.at(i, j);
            }
        }
        return result;
    }

    Matrix operator*(const Matrix& o) const {
        if (cols_ != o.rows_) {
            throw std::invalid_argument("Matrix multiplication: size mismatch");
        }
        Matrix result(rows_, o.cols_);
        for (int i = 0; i < rows_; ++i) {
            for (int j = 0; j < o.cols_; ++j) {
                double sum = 0.0;
                for (int k = 0; k < cols_; ++k) {
                    sum += data_[static_cast<size_t>(i) * static_cast<size_t>(cols_) + static_cast<size_t>(k)] *
                           o.at(k, j);
                }
                result.at(i, j) = sum;
            }
        }
        return result;
    }

    bool operator==(const Matrix& o) const {
        if (rows_ != o.rows_ || cols_ != o.cols_) {
            return false;
        }
        for (int i = 0; i < rows_; ++i) {
            for (int j = 0; j < cols_; ++j) {
                if (data_[static_cast<size_t>(i) * static_cast<size_t>(cols_) + static_cast<size_t>(j)] !=
                    o.data_[static_cast<size_t>(i) * static_cast<size_t>(o.cols_) + static_cast<size_t>(j)]) {
                    return false;
                }
            }
        }
        return true;
    }
};
