struct Node {
    int value;
    Node* next;
    Node(int v, Node* n = nullptr) : value(v), next(n) {}
};

class List {
    Node* head = nullptr;

public:
    List() = default;
    List(const List&) = delete;
    List& operator=(const List&) = delete;
    ~List() {
        Node* c = head;
        while (c) {
            delete c;
            c = c->next;
        }
    }

    void push_back(int v) {
        Node* n = new Node(v);
        Node* c = head;
        if (c) {
            while (c->next) c = c->next;
            c->next = n;
        } else {
            head = n;
        }
    }

    void remove_all(int v) {
        Node* c = head;
        while (c && c->next) {
            if (c->next->value == v) {
                delete c->next;
                c->next = c->next->next;
            } else {
                c = c->next;
            }
        }
    }

    void reverse() {
        Node* prev = nullptr;
        Node* c = head;
        while (c) {
            Node* nxt = c->next;
            c->next = prev;
            prev = c;
            c = nxt;
        }
        head = prev;
    }

    std::size_t size() const {
        std::size_t n = 0;
        for (Node* c = head; c; c = c->next) ++n;
        return n;
    }

    int at(std::size_t i) const {
        Node* c = head;
        for (std::size_t j = 0; j < i; ++j) {
            if (!c) throw std::out_of_range("index out of range");
            c = c->next;
        }
        if (!c) throw std::out_of_range("index out of range");
        return c->value;
    }
};
