def paginate(items, page, per_page=10):
    """Return the items on a 1-indexed page. Raise ValueError if page < 1 or per_page < 1."""
    if page < 1 or per_page < 1:
        raise ValueError("page and per_page must be >= 1")
    start = (page - 1) * per_page
    return items[start:start + per_page]


def word_freq(text, stop=None):
    """Return (word, count) pairs: case-insensitive, punctuation ignored, words in stop excluded,
    most common first, ties in alphabetical order."""
    if stop is None:
        stop = []
    import string
    stop_set = set(stop)
    counts = {}
    for token in text.split():
        # Strip punctuation and lowercase
        word = token.strip(string.punctuation).lower()
        if word:
            if word not in stop_set:
                counts[word] = counts.get(word, 0) + 1
    # Most common first; alphabetical order breaks ties
    return sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))


def merge_config(base, override):
    """Return a deep merge of override onto base. Nested dicts merge; other values are replaced.
    Neither argument may be changed."""
    out = {}
    out.update(base)

    for key, override_val in override.items():
        if isinstance(override_val, dict) and isinstance(out.get(key), dict):
            out[key] = merge_config(out[key], override_val)
        else:
            out[key] = override_val

    return out
