import csv
import decimal

def summarize_sales(path):
    valid_rows = 0
    invalid_rows = 0
    total_rev = decimal.Decimal("0")
    by_region = {}
    by_product = {}

    with open(path, "r", newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            try:
                qty = decimal.Decimal(row["qty"].strip())
                price = decimal.Decimal(row["price"].strip())
            except (KeyError, decimal.InvalidOperation, AttributeError):
                invalid_rows += 1
                continue

            if qty <= 0 or price < 0:
                invalid_rows += 1
                continue

            valid_rows += 1
            revenue = qty * price
            total_rev += revenue

            region = row["region"].strip()
            by_region[region] = by_region.get(region, decimal.Decimal("0")) + revenue

            product = row["product"].strip()
            by_product[product] = by_product.get(product, decimal.Decimal("0")) + revenue

    def round_rev(d):
        return float(d.quantize(decimal.Decimal("0.01")))

    if valid_rows == 0:
        return {
            "rows": 0,
            "skipped": invalid_rows,
            "total": 0.0,
            "by_region": {},
            "top_product": None,
        }

    total_rev_rounded = round_rev(total_rev)
    by_region_rounded = {k: round_rev(v) for k, v in by_region.items()}
    top_product = max(
        by_product,
        key=lambda p: (by_product[p], p)
    )

    return {
        "rows": valid_rows,
        "skipped": invalid_rows,
        "total": total_rev_rounded,
        "by_region": by_region_rounded,
        "top_product": top_product,
    }
