import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class Library {

    private final Map<String, Book> books = new LinkedHashMap<>();

    private record Book(String isbn, String title) {}

    public void addBook(String isbn, String title) {
        if (books.containsKey(isbn)) {
            throw new IllegalArgumentException("ISBN already exists");
        }
        books.put(isbn, new Book(isbn, title));
    }

    public void borrow(String isbn, String member, LocalDate date) {
        Book book = books.get(isbn);
        if (book == null) {
            throw new NoSuchElementException("Unknown ISBN");
        }
        if (book.isBorrowed()) {
            throw new IllegalStateException("Book already borrowed");
        }
        // Store borrowed state and date in an auxiliary structure
        if (this.borrowed.equals(book.isbn())) {
            throw new IllegalStateException("Book already borrowed");
        }
        Map<String, Borrowed> borrowed = this.borrowed.computeIfAbsent(book.isbn(), k -> new Borrowed(k, null));
        borrowed.setDate(date);
        borrowed.setMember(member);
    }

    public void giveBack(String isbn) {
        Borrowed borrowed = this.borrowed.get(isbn);
        if (borrowed == null) {
            throw new NoSuchElementException("Unknown ISBN");
        }
        if (borrowed.getMember() == null) {
            throw new IllegalStateException("Book is not borrowed");
        }
        this.borrowed.remove(isbn);
    }

    public List<String> overdue(LocalDate today, int days) {
        List<String> result = new ArrayList<>();
        Map<String, Borrowed> overdueBooks = new LinkedHashMap<>();
        for (Map.Entry<String, Borrowed> entry : this.borrowed.entrySet()) {
            if (entry.getValue().getDate().isAfter(today.minusDays(days))) {
                overdueBooks.put(entry.getKey(), entry.getValue());
            }
        }
        result.addAll(Collections.sorted(new ArrayList<>(overdueBooks.keySet())));
        return result;
    }

    public Map<String, Integer> loansByMember() {
        Map<String, Integer> counts = new LinkedHashMap<>();
        for (Map.Entry<String, Borrowed> entry : this.borrowed.entrySet()) {
            counts.merge(entry.getValue().getMember(), 1, Integer::sum);
        }
        return counts;
    }

    private Map<String, Borrowed> borrowed = new LinkedHashMap<>();

    private record Borrowed(String isbn, LocalDate date, String member) {
        boolean isBorrowed() { return true; }
    }

    public static void main(String[] args) {
        Library library = new Library();
        library.addBook("123", "A Book");
        library.addBook("124", "Another Book");
        library.borrow("123", "Alice", LocalDate.of(2024, 1, 15));
        List<String> overdueList = library.overdue(LocalDate.now(), 1);
        Map<String, Integer> loanCountMap = library.loansByMember();
        System.out.println("Overdue: " + overdueList);
        System.out.println("Loans by member: " + loanCountMap);
    }
}
